1	// === Types ===
2	type Customer = { yearsWithMHPCO: number };
3	type Item = { type: string; cursed?: boolean; enchantment?: number };
4	type Damage = { itemType: string; amount: number };
5	type Incident = { cause: string; damages: Damage[] };
6	type QuoteStep = { op: "quote"; items: Item[] };
7	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
8	type Step = QuoteStep | ClaimStep;
9	type Scenario = { customer: Customer; steps: Step[] };
10	type Policy = { items: Item[]; remainingCap: number };
11	
12	// === Premium constants ===
13	const PROCESSING_FEE = 5;
14	const FIRST_INSURANCE_RATE = 0.1;
15	const LOYALTY_DISCOUNT_RATE = 0.2;
16	const LOYALTY_YEARS_THRESHOLD = 2;
17	const FOLLOWUP_DISCOUNT_RATE = 0.15;
18	const CURSE_RATE = 0.5;
19	const HIGH_ENCHANTMENT_RATE = 0.3;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	// === Component-block constants ===
32	const BLOCK_SIZE = 3;
33	const COMPONENT_BLOCK_PRICE = 60;
34	const COMPONENT_TYPES = ["rune", "moonstone"];
35	
36	// === Policy / claim constants ===
37	const DEDUCTIBLE = 100;
38	const CAP_MULTIPLIER = 2;
39	const INSURANCE_VALUE_MULTIPLIER = 10;
40	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
41	const HALF_REIMBURSEMENT_RATE = 0.5;
42	
43	// === Generic helpers ===
44	const sumBy = <T>(items: T[], selector: (item: T) => number): number =>
45	  items.reduce((sum, item) => sum + selector(item), 0);
46	
47	const rateIfApplies = (applies: boolean, base: number, rate: number): number =>
48	  applies ? base * rate : 0;
49	
50	// === Base premium ===
51	const basePremium = (item: Item): number => {
52	  const price = BASE_PREMIUMS[item.type];
53	  if (price === undefined) throw new Error(`unknown item type: ${item.type}`);
54	  return price;
55	};
56	
57	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
58	
59	const isHighlyEnchanted = (item: Item): boolean =>
60	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_THRESHOLD;
61	
62	const isCursed = (item: Item): boolean => item.cursed ?? false;
63	
64	const itemSurcharge = (item: Item): number => {
65	  const base = basePremium(item);
66	  return rateIfApplies(isCursed(item), base, CURSE_RATE)
67	       + rateIfApplies(isHighlyEnchanted(item), base, HIGH_ENCHANTMENT_RATE);
68	};
69	
70	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
71	  sameTypeItems.length === BLOCK_SIZE && COMPONENT_TYPES.includes(sameTypeItems[0].type);
72	
73	const groupBasePremium = (sameTypeItems: Item[]): number =>
74	  isComponentBlock(sameTypeItems) ? COMPONENT_BLOCK_PRICE : sumBy(sameTypeItems, basePremium);
75	
76	const groupBy = <T>(items: T[], key: (item: T) => string): Map<string, T[]> => {
77	  const groups = new Map<string, T[]>();
78	  for (const item of items) {
79	    const k = key(item);
80	    const bucket = groups.get(k) ?? [];
81	    bucket.push(item);
82	    groups.set(k, bucket);
83	  }
84	  return groups;
85	};
86	
87	const totalBasePremium = (items: Item[]): number =>
88	  sumBy([...groupBy(items, (i) => i.type).values()], groupBasePremium);
89	
90	// === Policy-wide premium modifiers ===
91	const isLoyal = (customer: Customer): boolean =>
92	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
93	
94	const loyaltyDiscount = (base: number, customer: Customer): number =>
95	  rateIfApplies(isLoyal(customer), base, LOYALTY_DISCOUNT_RATE);
96	
97	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
98	
99	const followupDiscount = (base: number, isFollowup: boolean): number =>
100	  rateIfApplies(isFollowup, base, FOLLOWUP_DISCOUNT_RATE);
101	
102	const perItemSurcharges = (items: Item[]): number => sumBy(items, itemSurcharge);
103	
104	const premiumForItems = (items: Item[], customer: Customer, isFollowup: boolean): number => {
105	  const base = totalBasePremium(items);
106	  const surcharges = perItemSurcharges(items) + firstInsuranceSurcharge(base);
107	  const discounts = loyaltyDiscount(base, customer) + followupDiscount(base, isFollowup);
108	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
109	};
110	
111	// === Insurance / cap ===
112	const insuranceValue = (item: Item): number => basePremium(item) * INSURANCE_VALUE_MULTIPLIER;
113	
114	const insuranceSum = (items: Item[]): number => sumBy(items, insuranceValue);
115	
116	const policyCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLIER;
117	
118	// === Claim payout ===
119	const qualifiesForHalfReimbursement = (item: Item): boolean =>
120	  enchantmentLevel(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
121	
122	const reimbursementRate = (item: Item): number =>
123	  qualifiesForHalfReimbursement(item) ? HALF_REIMBURSEMENT_RATE : 1;
124	
125	const applyDeductible = (amount: number): number => Math.max(0, amount - DEDUCTIBLE);
126	
127	const findInsuredItem = (items: Item[], itemType: string): Item => {
128	  const item = items.find((i) => i.type === itemType);
129	  if (item === undefined) throw new Error(`uninsured item type: ${itemType}`);
130	  return item;
131	};
132	
133	const damagePayout = (damage: Damage, item: Item): number =>
134	  applyDeductible(damage.amount * reimbursementRate(item));
135	
136	const assertNonNegativeAmount = (damage: Damage): void => {
137	  if (damage.amount < 0) throw new Error(`negative damage amount: ${damage.amount}`);
138	};
139	
140	const assertDamageCountsWithinInsured = (damages: Damage[], items: Item[]): void => {
141	  const insuredByType = groupBy(items, (i) => i.type);
142	  const damagesByType = groupBy(damages, (d) => d.itemType);
143	  for (const [itemType, sameTypeDamages] of damagesByType) {
144	    if (sameTypeDamages.length > (insuredByType.get(itemType)?.length ?? 0)) {
145	      throw new Error(`more damages of type ${itemType} than insured`);
146	    }
147	  }
148	};
149	
150	const assertValidDamages = (damages: Damage[], items: Item[]): void => {
151	  damages.forEach(assertNonNegativeAmount);
152	  assertDamageCountsWithinInsured(damages, items);
153	};
154	
155	const claimPayout = (damages: Damage[], policy: Policy): number => {
156	  assertValidDamages(damages, policy.items);
157	  const rawPayout = sumBy(damages, (d) => damagePayout(d, findInsuredItem(policy.items, d.itemType)));
158	  return Math.min(Math.floor(rawPayout), policy.remainingCap);
159	};
160	
161	// === Step handlers ===
162	const handleQuote = ({ items }: QuoteStep, customer: Customer, policies: Policy[]) => {
163	  const isFollowup = policies.length > 0;
164	  const premium = premiumForItems(items, customer, isFollowup);
165	  policies.push({ items, remainingCap: policyCap(items) });
166	  return { premium };
167	};
168	
169	const handleClaim = ({ policy: policyIndex, incident }: ClaimStep, policies: Policy[]) => {
170	  const policy = policies[policyIndex];
171	  const payout = claimPayout(incident.damages, policy);
172	  policy.remainingCap -= payout;
173	  return { payout, remainingCap: policy.remainingCap };
174	};
175	
176	export const runScenario = ({ customer, steps }: Scenario): unknown => {
177	  const policies: Policy[] = [];
178	  const results = steps.map((step) =>
179	    step.op === "quote" ? handleQuote(step, customer, policies) : handleClaim(step, policies),
180	  );
181	  return { results };
182	};
